import{_ as t,o as s,c as e,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p="/assets/app_list.ZgEYszRv.jpg",l="/assets/app_toast.MpXd9QXv.jpg",n="/assets/app_detail.Du2PMI4j.jpg",_=JSON.parse('{"title":"应用管理","description":"","frontmatter":{"title":"应用管理"},"headers":[],"relativePath":"app-center/guide/manage-apps.md","filePath":"app-center/guide/manage-apps.md","lastUpdated":1794381603000}'),o={name:"app-center/guide/manage-apps.md"};function r(d,a,c,h,g,k){return s(),e("div",null,[...a[0]||(a[0]=[i('<h3 id="查看已购应用" tabindex="-1">查看已购应用 <a class="header-anchor" href="#查看已购应用" aria-label="Permalink to &quot;查看已购应用&quot;">​</a></h3><p>应用购买完成后，您可以在“客户中心 → 产品管理 → 我的产品与服务”页面查看，查看方式与原有的 VPS/裸机云产品相同。</p><p><img src="'+p+'" alt="已购应用列表"></p><p>在产品列表中，应用会在名称前显示对应的图标，方便您快速识别。将鼠标悬浮在产品名称上，可以看到应用的基本信息，包括应用名称、版本号及访问地址等。</p><p><img src="'+l+'" alt="应用信息悬浮提示"></p><h3 id="应用详情页" tabindex="-1">应用详情页 <a class="header-anchor" href="#应用详情页" aria-label="Permalink to &quot;应用详情页&quot;">​</a></h3><p>点击产品名称进入详情页，页面布局与原有的 VPS/裸机云产品管理页面相同。</p><p>针对应用，我们在右侧管理面板中新增了“应用”标签页。点击该标签，您可以查看：</p><ul><li>应用名称和版本号</li><li>访问地址等信息</li><li>应用的参数配置详情</li><li>应用文档链接（点击可查看完整的应用使用文档）</li></ul><p><img src="'+n+'" alt="应用详情页"></p><blockquote><p><strong>注意</strong></p><p>首次创建或者重装应用后，应用需要约 1~3 分钟完成加载。建议在操作后稍作等待再访问应用，避免因服务未就绪而导致访问失败。</p></blockquote><h3 id="访问凭证说明" tabindex="-1">访问凭证说明 <a class="header-anchor" href="#访问凭证说明" aria-label="Permalink to &quot;访问凭证说明&quot;">​</a></h3><p>所有应用涉及的访问信息（如数据库密码、管理员账号等）均存放于服务器的凭证文件中：</p><ul><li>文件路径：<code>/opt/cloud/&lt;应用名称&gt;/credentials.txt</code></li><li>示例：WordPress 应用的凭证文件为 <code>/opt/cloud/wordpress/credentials.txt</code></li></ul><p>您可以通过 SSH 登录服务器后查看该文件，获取完整的访问信息：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/cloud/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">应用名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/credentials.txt</span></span></code></pre></div><h3 id="运维操作" tabindex="-1">运维操作 <a class="header-anchor" href="#运维操作" aria-label="Permalink to &quot;运维操作&quot;">​</a></h3><p>应用本质上运行在 VPS 或裸机云服务器上，您可以像管理普通云服务器一样进行运维操作，如开机、关机、重启等。</p><p>如需了解应用相关的运维命令（如启动、停止、备份等），可以通过 SSH 登录服务器查看。登录后的欢迎信息中会显示该应用的常用管理命令，您也可以参考各应用的使用指南获取更多信息。</p>',19)])])}const m=t(o,[["render",r]]);export{_ as __pageData,m as default};
